<?php/* Recuperation du paiement d'un client */$requete_paie = $bdd->prepare("SELECT * FROM v_factglobale WHERE  id_hotel=:id_hotel AND type IS NULL");/* Fin Recuperation */$requete_paie->BindParam(':id_hotel', $_SESSION['id_hotel']);$requete_paie->execute();while ($donnees = $requete_paie->fetch()) {    $id_fact = $donnees['id_fact'];    $id_client = $donnees['id_client'];    $id_res_ch = $donnees['res_ch_id'];    $id_ch = $donnees['id_ch'];    $statut_ch=$donnees['statut'];    $chmonnaie = $donnees['monnaie'];    $tarif_ch = $donnees['tarif_ch'];    $dte_a = $donnees['date_occ'];    $dte_s = $donnees['date_lib'];    $montant_total= $donnees['montant_total'];    date_default_timezone_set('Europe/Paris');    $dte = date('H:i:s');    $temps_actuel = $dte;    if ($temps_actuel >= $temps_sortie) {        $dte_now = date('Y-m-d', time() + 86400);    } else {        $dte_now = date('Y-m-d');    }    /* Nombre de jour effectué */    //Empecher incrementation de jour pour client libere chambre    if($statut_ch=='occupe'){        $Nombres_jours = NbJours($dte_a, $dte_now);    }else{        $Nombres_jours = NbJours($dte_a, $dte_s);    }    $nb_jrs = $Nombres_jours;    $nb_jr = $nb_jrs - 1;    if ($nb_jr == 0) {        $nb_jr++;    }    $nbre_jr = $nb_jr;    /* Fin Nombre de jour effectué*/    if ($chmonnaie = 'USD') {        $tarif_ch = round($tarif_ch, 2);    } else {        $tarif_ch = round($tarif_ch * 1 / $tauxdollar, 2);    }    $tarif_net = $tarif_ch * $nbre_jr;    if($tarif_net>$montant_total){        //update montant total facture        $requete = $bdd->prepare("UPDATE t_facture  SET montant_total =:montant_total WHERE id_fact=:id_fact");        $requete->BindParam(':id_fact', $id_fact);        $requete->BindParam(':montant_total', $tarif_net);        $requete->execute();    }}/* Fin de la Recuperation du paiement d'un client */?>